def compute_spawn(adjusted_fitness, previous_sizes, pop_size, min_species_size):
        """Compute the proper number of offspring per species (proportional to fitness)."""
        # Compute the number of offspring for each species
        spawn_per_species = np.array(
            [
                int(
                    np.ceil(
                        (adjusted_fitness[i] / adjusted_fitness.sum()) * pop_size
                    )
                )
                for i in range(len(previous_sizes))
            ]
        )
        # Make sure that the total number of offspring is equal to the population size
        spawn_per_species = np.minimum(spawn_per_species, pop_size)
        # Make sure that each species has at least min_species_size offspring
        spawn_per_species = np.maximum(spawn_per_species, min_species_size)
        # Make sure that the total number of offspring is equal to the population size
        spawn_per_species = np.minimum(spawn_per_species, pop_size)
        return spawn_per_species

