def get_objects(self, ids, **args):
        """Fetches all of the given object from the graph.

        We return a map from ID to object. If any of the IDs are
        invalid, we raise an exception.
        """
        if not ids:
            return {}

        # We need to fetch the objects in batches, because the
        # Graph API doesn't support fetching multiple objects at
        # once.
        objects = {}
        for batch in self._batch_fetch(ids, **args):
            for obj in batch:
                objects[obj.id] = obj
        return objects

