        :param attribute_filter:
        :type attribute_filter: prestans.parser.AttributeFilter
        :param minified:
        :type minified: bool
        :return:
        """
        if value is None:
            return

        if not isinstance(value, list):
            raise ValueError("value must be list")

        for item in value:
            if not isinstance(item, dict):
                raise ValueError("item must be dict")

            if not item:
