def in_check(self, position, location=None):
        """
        Finds if the king is in check or if both kings are touching.

        :type: position: Board
        :return: bool
        """
        if location is None:
            location = self.location
        if self.color == 'white':
            if self.board.get_piece(location) == 'black king':
                return True
            for piece in self.board.pieces:
                if piece.color == 'black':
                    if piece.location == location:
                        return True
                    if piece.location == self.location:
                        return True
        else:
            if self.board.get_piece(location) == 'white king':
                return True
            for piece in self.board.pieces:
                if piece.color == 'white':
                    if piece.location == location:
                        return True
                    if piece.location == self.location:
                        return True
        return False

