def _compute_relative_probs(self, prob_dict):
        """ computes the relative probabilities for every state """
        # compute the sum of all probabilities
        sum_prob = 0
        for state in prob_dict:
            sum_prob += prob_dict[state]

        # compute the relative probabilities
        for state in prob_dict:
            prob_dict[state] = prob_dict[state] / sum_prob

        return prob_dict

