def recursive_symlink_dirs(source_d, destination_d):
    """
    Create dirs and symlink all files recursively from source_d, ignoring
    errors (e.g. existing files)
    """
    for d in os.listdir(source_d):
        source_d_path = os.path.join(source_d, d)
        destination_d_path = os.path.join(destination_d, d)
        if os.path.isdir(source_d_path):
            if not os.path.exists(destination_d_path):
                os.makedirs(destination_d_path)
            recursive_symlink_dirs(source_d_path, destination_d_path)
        else:
            try:
                os.symlink(source_d_path, destination_d_path)
            except OSError:
                pass

