def git_version():
    """Constructs a version string of the form:

           <tag>[.<distance-from-tag>[+<branch-name-if-not-master>]]

       Master is understood to be always buildable and thus untagged
       versions are treated as patch levels. Branches not master are treated
       as PEP-440 "local version identifiers".
    """
    try:
        tag = subprocess.check_output(['git', 'describe', '--tags', '--dirty']).strip()
    except subprocess.CalledProcessError:
        tag = None
    try:
        distance = subprocess.check_output(['git','rev-list', '--count', 'HEAD']).strip()
    except subprocess.CalledProcessError:
        distance = None
    try:
        branch = subprocess.check_output(['git','rev-parse', '--abbrev-ref', 'HEAD']).strip()
    except subprocess.CalledProcessError:
        branch = None
    if branch =='master':
        branch = None
    if tag is None:
        if distance is None:
            return '0'
        else:
            return '0.dev%s' % distance
    else:
        if distance is None:
            return tag
        else:
            return '%s.dev%s' % (tag, distance)
    if branch is not None:
        return '%s+%s' % (tag, branch)
    else:
        return tag

