def _to_xml(self, xml, data, key=None):
        """ Recursively convert the data into xml.

        This function was originally copied from the
        `Piston project <https://bitbucket.org/jespern/django-piston/>`_
        It has been modified since.

        :param xml: the xml document
        :type xml: SimplerXMLGenerator
        :param data: data to be formatted
        :param key: name of the parent element (for root this is ``None``)
        """
        if isinstance(data, dict):
            for k, v in data.items():
                self._to_xml(xml, v, k)
        elif isinstance(data, list):
            for item in data:
                self._to_xml(xml, item, key)
        elif isinstance(data, tuple):
            for item in data:
                self._to_xml(xml, item, key)
        elif isinstance(data, (int, float, bool, basestring)):
            xml.startElement(key, {})
            xml.characters(unicode(data))
            xml.endElement(key)
        elif isinstance(data, datetime):
            xml.startElement(key, {})
            xml.characters(data.isoformat())
            xml.endElement(key)
        elif isinstance(data, date):
            xml.startElement(key, {})
            xml.characters(data.isoformat())
            xml.endElement(key)
        elif isinstance(data, time):
            xml.startElement(key, {})
            xml.characters(data.isoformat())
            xml.endElement(key)
        elif isinstance(data, timedelta):
            xml.startElement(key, {})
            xml.characters(data.isoformat())
            xml.endElement(key)
        elif isinstance(data, uuid.UUID):
            xml.startElement(key, {})
            xml.characters(data.hex)
            xml.endElement(key)
        elif isinstance(data, (set, frozenset)):
            for item in data:
                self._to_xml(xml, item, key)
        elif isinstance(data, (list, tuple)):
            for item in data:
                self._to_xml(xml, item, key)
        elif isinstance(data, (dict, OrderedDict)):
            for k, v in data.items():
                self._to_xml(xml, v, k)
        elif isinstance(data, object):
            self._to_xml(xml, data.__dict__, key)
        else:
            raise TypeError('Cannot serialize %r (type %s)' % (data, type(data)))

