def _cmp(self, other):
        """
        Comparator function for two :class:`~pywbem.CIMQualifier` objects.

        The comparison is based on their public attributes, in descending
        precedence:

        * `name`
        * `type`
        * `value`
        * `propagated`
        * `overridable`
        * `tosubclass`
        * `toinstance`
        * `translatable`

        The comparison takes into account any case insensitivities described
        for these attributes.
        """
        if self.name!= other.name:
            return cmp(self.name, other.name)
        if self.type!= other.type:
            return cmp(self.type, other.type)
        if self.value!= other.value:
            return cmp(self.value, other.value)
        if self.propagated!= other.propagated:
            return cmp(self.propagated, other.propagated)
        if self.overridable!= other.overridable:
            return cmp(self.overridable, other.overridable)
        if self.tosubclass!= other.tosubclass:
            return cmp(self.tosubclass, other.tosubclass)
        if self.toinstance!= other.toinstance:
            return cmp(self.toinstance, other.toinstance)
        if self.translatable!= other.translatable:
            return cmp(self.translatable, other.translatable)
        return 0

