            words = args[0]
            if isinstance(words, str):
                words = [words]
            elif isinstance(words, list):
                pass
            else:
                raise ValueError("words must be a list or string")
        elif len(args) == 0:
            words = self.words
        else:
            raise ValueError("distance can only take one or zero arguments")
        if "n" in kwargs:
            n = kwargs["n"]
        else:
