def build_trie(pattern_filename, pattern_format, encoding, on_word_boundaries):
    """
    Constructs a finite state machine for performing string rewriting.

    Arguments:
    - `pattern_filename`:
    - `pattern_format`:
    - `encoding`:
    - `on_word_boundaries`:
    """
    trie = {}
    with open(pattern_filename, encoding=encoding) as pattern_file:
        for line in pattern_file:
            if line.startswith('#'):
                continue
            line = line.rstrip('\n')
            if line == '':
                continue
            if pattern_format =='regex':
                pattern = re.compile(line)
            elif pattern_format =='simple':
                pattern = line
            else:
                raise ValueError('Unknown pattern format: %s' % pattern_format)
            trie[pattern] = on_word_boundaries
    return trie

