def _find_next_widget(self, direction, stay_in_col=False, start_at=None,
                          wrap=False):
        """
        Find the next widget to get the focus, stopping at the start/end of the list if hit.

        :param direction: The direction to move through the widgets.
        :param stay_in_col: Whether to limit search to current column.
        :param start_at: Optional starting point in current column.
        :param wrap: Whether to wrap around columns when at the end.
        """
        if direction == 'down':
            if stay_in_col:
                if start_at is None:
                    start_at = self.current_col_index
                for i in range(start_at, len(self.current_col)):
                    widget = self.current_col[i]
                    if widget.enabled:
                        return widget
                if wrap:
                    for i in range(0, start_at):
                        widget = self.current_col[i]
                        if widget.enabled:
                            return widget
            else:
                for col in self.columns:
                    for widget in col:
                        if widget.enabled:
                            return widget
        elif direction == 'up':
            if stay_in_col:
                if start_at is None:
                    start_at = self.current_col_index
                for i in range(start_at, -1, -1):
                    widget = self.current_col[i]
                    if widget.enabled:
                        return widget
                if wrap:
                    for i in range(len(self.current_col) - 1, start_at, -1):
                        widget = self.current_col[i]
                        if widget.enabled:
                            return widget
            else:
                for col in reversed(self.columns):
                    for widget in reversed(col):
                        if widget.enabled:
                            return widget
        elif direction == 'left':
            if self.current_col_index > 0:
                return self.current_col[self.current_col_index - 1]
            elif wrap:
                return self.current_col[len(self.current_col) - 1]
        elif direction == 'right':
            if self.current_col_index < len(self.current_col) - 1:
                return self.current_col[self.current_col_index + 1]
            elif wrap:
                return self.current_col[0]

