def name_tree(tree):
    """
    Names all the tree nodes that are not named or have non-unique names, with unique names.

    :param tree: tree to be named
    :type tree: ete3.Tree

    :return: void, modifies the original tree
    """
    if tree.name is None:
        tree.name = tree.get_tree_root().name
    if tree.name is None:
        tree.name = "unnamed"
    if tree.name in tree.get_tree_root().get_descendants():
        tree.name = tree.name + "_1"
    for node in tree.traverse():
        if node.name is None:
            node.name = tree.name + "_" + str(node.get_tree_root().get_distance(node))
        if node.name in node.get_tree_root().get_descendants():
            node.name = node.name + "_" + str(node.get_tree_root().get_distance(node))

