def master_main(painter, router, select, delay):
    """
    Loop until CTRL+C is pressed, waiting for the next result delivered by the
    Select. Use parse_output() to turn that result ('ps' command output) into
    rich data, and finally repaint the screen if the repaint delay has passed.
    """
    while True:
        try:
            # Wait for the next result delivered by the Select.
            result = select.select(delay)
            if result:
                # Parse the output of the 'ps' command.
                rich_data = parse_output(result[0])
                # If the repaint delay has passed, repaint the screen.
                if time.time() > delay:
                    painter.paint(rich_data)
                    delay = time.time() + REPAINT_DELAY
        except KeyboardInterrupt:
            break

