    Return a list of IPs of the nameservers for ``domain``

    If ``resolve`` is False, don't resolve names.

    CLI Example:

    .. code-block:: bash

        salt ns1 dig.NS google.com
    """
    if nameserver is None:
        nameserver = _get_nameserver()
    if resolve:
        return [
            socket.gethostbyname(nameserver)
            for nameserver in NS(domain, resolve=False, nameserver=nameserver)
        ]
    else:
        return [nameserver]

