def _dump_multipolygon(obj, big_endian, meta):
    """
    Dump a GeoJSON-like `dict` to a multipolygon WKB string.

    Input parameters and output are similar to :funct:`_dump_point`.
    """
    if not isinstance(obj, dict):
        raise TypeError("Expected dict, got %s" % type(obj))
    if obj.get("type")!= "MultiPolygon":
        raise ValueError("Expected MultiPolygon, got %s" % obj.get("type"))
    if not isinstance(obj.get("coordinates"), list):
        raise ValueError("Expected list of coordinates, got %s" % type(obj.get("coordinates")))
    if not all(isinstance(x, list) for x in obj.get("coordinates")):
        raise ValueError("Expected list of lists of coordinates, got %s" % type(obj.get("coordinates")))
    if not all(all(isinstance(y, list) for y in x) for x in obj.get("coordinates")):
        raise ValueError("Expected list of lists of lists of coordinates, got %s" % type(obj.get("coordinates")))
    if not all(all(len(y) == 2 for y in x) for x in obj.get("coordinates")):
        raise ValueError("Expected list of lists of lists of 2-tuples, got %s" % type(obj.get("coordinates")))
    if not all(all(all(isinstance(z, float) for z in y) for y in x) for x in obj.get("coordinates")):
        raise ValueError("Expected list of lists of lists of floats, got %s" % type(obj.get("coordinates")))

    # First, dump the number of polygons
    polygons = obj.get("coordinates")
    n_polygons = len(polygons)
    if n_polygons > 255:
        raise ValueError("Expected at most 255 polygons, got %d" % n_polygons)
    _dump_int(n_polygons, big_endian, meta)

    # Then, dump each polygon
    for polygon in polygons:
        _dump_polygon(polygon, big_endian, meta)

