        """ Makes GLfloat or GLuint vector containing float or uint args.
        By default, newtype is 'float', but can be set to 'int' to make
        uint list. """
        if dtype == float:
            return (GLfloat * len(data))(*data)
        elif dtype == int:
            return (GLuint * len(data))(*data)
        else:
            raise TypeError("dtype must be float or int")

