def update(self, other=None, **kwargs):
        """Takes the same arguments as the update method in the builtin dict
        class. However, this version returns a new ImmutableDict instead of
        modifying in-place."""
        if other is None:
            return self
        if isinstance(other, ImmutableDict):
            return ImmutableDict(other, **kwargs)
        return ImmutableDict(self, **kwargs).update(other, **kwargs)

