def calculateDatasetItems(self, scene, datasets):
        """
        Syncs the scene together with the given datasets to make sure we
        have the proper number of items, by removing non-existant datasets
        and adding new ones.

        :param      scene    | <XChartScene>
                    datasets | <XChartDataset>

        :return     {<XChartDataset>: <XChartDatasetItem>, ..}
        """
        # Get the current items
        currentItems = {}
        for item in scene.items():
            if isinstance(item, XChartDatasetItem):
                currentItems[item.dataset] = item

        # Remove items that are not in the datasets
        for dataset in currentItems.keys():
            if dataset not in datasets:
                scene.removeItem(currentItems[dataset])
                del currentItems[dataset]

        # Add new items
        for dataset in datasets:
            if dataset not in currentItems:
                item = XChartDatasetItem(scene, dataset)
                scene.addItem(item)
                currentItems[dataset] = item

        return currentItems

