def _inherited_dashboard(dashboard, base_dashboards_from_pillar, ret):
    """Return a dashboard with properties from parents."""
    for base_dashboard in base_dashboards_from_pillar:
        if base_dashboard not in ret:
            ret[base_dashboard] = {}
        for key, value in dashboard[base_dashboard].items():
            if key not in ret[base_dashboard]:
                ret[base_dashboard][key] = value
            elif isinstance(value, dict):
                ret[base_dashboard][key] = _inherited_dashboard(
                    value, base_dashboards_from_pillar, ret
                )
    return ret

