    """
    .. versionadded:: 2015.8.0

    Return information about a management_certificate

    CLI Example:

    .. code-block:: bash

        salt-cloud -f get_management_certificate my-azure name=my_management_certificate \\
            thumbalgorithm=sha1 thumbprint=0123456789ABCDEF
    """
    if kwargs is None:
        kwargs = {}
    if conn is None:
        conn = _get_conn(kwargs)
    if call is None:
        call = _get_call(kwargs)

    thumbprint = kwargs.get("thumbprint")
    thumbalgorithm = kwargs.get("thumbalgorithm")

    if thumbprint is None:
        raise SaltCloudSystemExit(
            "The thumbprint argument is required for management_certificate"
        )

    if thumbalgorithm is None:
        raise SaltCloudSystemExit(
            "The thumbalgorithm argument is required for management_certificate"
        )

    management_certificate = conn.get_management_certificate(
        thumbprint, thumbalgorithm
    )

    if management_certificate is None:
        raise SaltCloudSystemExit(
            "The management_certificate {0} was not found".format(thumbprint)
        )

    return _format_management_certificate(
        management_certificate, call=call, kwargs=kwargs
    )

