def clear(**kwargs):
    """Clear the specified names from the specified databases.

    This can be highly destructive as it destroys tables and when all names
    are removed from a database, the database itself.
    """
    dbs = kwargs.get('db', None)
    names = kwargs.get('name', None)
    if not dbs:
        raise ValueError('You must specify a database to clear.')
    if not names:
        raise ValueError('You must specify a name to clear.')
    for db in dbs:
        for name in names:
            try:
                db.drop_table(name)
            except Exception:
                pass
            try:
                db.drop_table(name + '_meta')
            except Exception:
                pass
            try:
                db.drop_table(name + '_log')
