        Raises a ValueError if the value required and not set, not valid,
        not correctly coerced, etc.

        .. note::

            Unlike :code:`validate`, this method requires instance to be
            a HasProperties instance; it cannot be None.
        """
        if not isinstance(instance, HasProperties):
            raise ValueError('instance must be a HasProperties instance')
        if value is None:
            value = instance.get_property(self.name)
        if value is None:
            if self.required:
                raise ValueError('required property %s not set' % self.name)
            return True
        if not self.validate(value):
            raise ValueError('invalid value %s for property %s' % (value, self.name))
        if self.coerce:
            try:
                value = self.coerce(value)
            except ValueError:
                raise ValueError('invalid value %s for property %s' % (value, self.name))
        return True

