def create_date(past=False, max_years_future=10, max_years_past=10):
    """
    Create a random valid date
    If past, then dates can be in the past
    If into the future, then no more than max_years into the future
    If it's not, then it can't be any older than max_years_past
    """
    if past:
        start = datetime.datetime.now() - datetime.timedelta(days=365 * max_years_past)
        end = datetime.datetime.now() - datetime.timedelta(days=365 * max_years_future)
    else:
        start = datetime.datetime.now() + datetime.timedelta(days=365 * max_years_future)
        end = datetime.datetime.now() + datetime.timedelta(days=365 * max_years_past)
    return random_date(start, end)

