            raise IOError("Invalid file format: %s" % filepath)
        if data['version']!= 1:
            raise IOError("Invalid file format: %s" % filepath)
        if not isinstance(data['modules'], dict):
            raise IOError("Invalid file format: %s" % filepath)
        if not isinstance(data['dependencies'], dict):
            raise IOError("Invalid file format: %s" % filepath)
        if not isinstance(data['recursive'], bool):
            raise IOError("Invalid file format: %s" % filepath)
        if not isinstance(data['greedy'], bool):
            raise IOError("Invalid file format: %s" % filepath)
