def serialize_header(self, pyobj, typecode=None, **kw):
        """Serialize a Python object in SOAP-ENV:Header, make
        sure everything in Header unique (no #href).  Must call
        serialize first to create a document.

        Parameters: 
            pyobjs -- instances to serialize in SOAP Header
            typecode -- default typecode
        """
        if not self.doc:
            raise TypeError("Must call serialize first")
        if not typecode:
            typecode = self.typecode
        if not isinstance(pyobj, (list, tuple)):
            pyobj = [pyobj]
        for obj in pyobj:
            if not isinstance(obj, self.typecode.type):
                raise TypeError("Must be %s" % self.typecode.type)
            if not obj.is_header:
                raise TypeError("Must be in SOAP-ENV:Header")
        for obj in pyobj:
            if obj.is_header:
                obj.is_header = False
        self.doc.header.extend(pyobj)

