def match_rules_context(tree, rules, parent_context={}):
    """Recursively matches a Tree structure with rules and returns context

    Args:
        tree (Tree): Parsed tree structure
        rules (dict): See match_rules
        parent_context (dict): Context of parent call
    Returns:
        dict: Context matched dictionary of matched rules or
        None if no match
    """
    if not isinstance(tree, Tree):
        raise TypeError("tree must be a Tree")
    if not isinstance(rules, dict):
        raise TypeError("rules must be a dict")
    if not isinstance(parent_context, dict):
        raise TypeError("parent_context must be a dict")

    context = {}
    for rule_name, rule_value in rules.items():
        if isinstance(rule_value, dict):
            context[rule_name] = match_rules_context(tree, rule_value, context)
        elif isinstance(rule_value, list):
            context[rule_name] = match_rules_context_list(tree, rule_value, context)
        else:
            context[rule_name] = match_rules_context_value(tree, rule_value, context)
    return context

