def mag_inclination(RAW_IMU, ATTITUDE, declination=None):
    """give the magnitude of the discrepancy between observed and expected magnetic field"""
    if declination is None:
        declination = 0
    mag_inclination = np.sqrt(
        (ATTITUDE.mag_x - RAW_IMU.mag_x) ** 2
        + (ATTITUDE.mag_y - RAW_IMU.mag_y) ** 2
        + (ATTITUDE.mag_z - RAW_IMU.mag_z) ** 2
    )
    return mag_inclination

