		:return: The charset of the request.
		:rtype: str
		"""
		content_type = self.headers.get('Content-Type', '')
		if ';' in content_type:
			content_type, params = content_type.split(';', 1)
		else:
			params = ''

		if 'charset=' in params:
			charset = params.split('charset=', 1)[1]
			charset = charset.split(';', 1)[0]
