    if not os.path.exists(input_file):
        raise Exception("Input file does not exist: %s" % input_file)

    if not os.path.exists(os.path.dirname(output_file)):
        os.makedirs(os.path.dirname(output_file))

    if not os.path.exists(output_file) or os.path.getmtime(input_file) > os.path.getmtime(output_file):
        print("Compiling %s to %s" % (input_file, output_file))
        with open(output_file, 'w') as f:
            f.write(lessc.compile(input_file, compress=True))

