def _edit_linux_cmdline(cmdline, state, name, value=None):
    """
    Return a new Linux command line, with parameter `name` added,
    replaced, or removed.
    """
    if value is None:
        # Remove parameter.
        return cmdline.replace(name, '')
    else:
        # Add or replace parameter.
        if name in cmdline:
            return cmdline.replace(name, '%s=%s' % (name, value))
        else:
            return '%s %s=%s' % (cmdline, name, value)

