def parse_path(f1, f2):

    """Parse two input arguments and return two lists of file names"""

    # Parse the first file name
    f1_list = []
    if os.path.isdir(f1):
        for root, dirs, files in os.walk(f1):
            for f in files:
                f1_list.append(os.path.join(root, f))
    else:
        f1_list.append(f1)

    # Parse the second file name
    f2_list = []
    if os.path.isdir(f2):
        for root, dirs, files in os.walk(f2):
            for f in files:
                f2_list.append(os.path.join(root, f))
    else:
        f2_list.append(f2)

    return f1_list, f2_list

