def handleError(self, test, err, capt=None):
        """
        After a test error, we want to record testcase run information.
        "Error" also encompasses any states other than Pass or Fail, so we
        check for those first.
        """
        if err.type == TestError:
            # TestError is a subclass of Exception, so we can just check for
            # the type.
            self.recordError(test, err)
        elif err.type == TestSkipped:
            self.recordSkip(test, err)
        elif err.type == TestFailed:
            self.recordFail(test, err)
        elif err.type == TestPassed:
            self.recordPass(test, err)
        elif err.type == TestAborted:
            self.recordAbort(test, err)
        else:
            # We don't know what this is, so we'll just record it as a
            # failure.
            self.recordFail(test, err)

        # If we have a capturer, we can use it to get the traceback.
        if capt:
            self.recordTraceback(test, capt)

