def set_expire(name, expire):
    """
    Sets the time at which the account expires (in seconds since the UNIX
    epoch). See ``man 8 usermod`` on NetBSD and OpenBSD or ``man 8 pw`` on
    FreeBSD.

    A value of ``0`` sets the account to never expire.

    CLI Example:

    .. code-block:: bash

        salt '*' shadow.set_expire username 1419980400
    """
    ret = {}
    if not _check_user(name):
        ret[name] = {'comment': 'User does not exist','result': False}
        return ret
    if not _check_expire(expire):
        ret[name] = {'comment': 'Invalid expire value','result': False}
        return ret
    cmd = ['usermod', '-e', expire, name]
    ret[name] = __salt__['cmd.run_all'](cmd)
    return ret

