def strip_tree(node,
               # Runtime optimization
               iter_node=iter_node, special=ast.AST,
               list=list, isinstance=isinstance, type=type, len=len):
    """Strips an AST by removing all attributes not in _fields.

    Returns a set of the names of all attributes stripped.

    This canonicalizes two trees for comparison purposes.
    """
    if isinstance(node, special):
        # Strip all attributes not in _fields.
        for field in node._fields:
            if hasattr(node, field):
                setattr(node, field, strip_tree(getattr(node, field),
                                                iter_node=iter_node,
                                                special=special,
                                                list=list,
                                                isinstance=isinstance,
                                                type=type,
                                                len=len))
        # Strip all attributes not in _fields.
        for field in node._attributes:
            if hasattr(node, field):
                setattr(node, field, strip_tree(getattr(node, field),
                                                iter_node=iter_node,
                                                special=special,
                                                list=list,
                                                isinstance=isinstance,
                                                type=type,
                                                len=len))
        return set(node._fields) | set(node._attributes)
    elif iter_node(node):
        # Strip all attributes not in _fields.
        for i, child in enumerate(node):
            node[i] = strip_tree(child, iter_node=iter_node,
                                 special=special, list=list,
                                 isinstance=isinstance, type=type,
                                 len=len)
        return set()
    else:
        return set()

