def download(timestamp, dataset, path=None, products=None,
             levels=None, offset=0):
    """save GFS grib file to DATA_PATH.

    Args:
        dataset(function): naming convention function.  eg. pgrb2
        timestamp(datetime): ???
        path(str): if None defaults to DATA_PATH
        products(list): TMP, etc. if None downloads all.
        layers(list): surface, etc. if None downloads all.
        offset(int): should be multiple of 3
    """
    if path is None:
        path = DATA_PATH
    if products is None:
        products = PRODUCTS
    if levels is None:
        levels = LEVELS
    if offset % 3!= 0:
        raise ValueError('offset must be multiple of 3')
    if offset < 0:
        raise ValueError('offset must be positive')
    if offset > 24:
        raise ValueError('offset must be less than 24')
    if offset > 0:
        timestamp = timestamp + timedelta(hours=offset)
    for product in products:
        for level in levels:
            filename = dataset(timestamp, product, level)
            url = URL_TEMPLATE.format(filename)
            filepath = os.path.join(path, filename)
            if not os.path.exists(filepath):
                print('downloading', url)
                r = requests.get(url)
