def git_clone(uri, pull=True, reflect=False, cache_dir=None, chdir=True):
    """
    Given a git repo, clone (cache) it locally.

    :param uri: git repo uri
    :param pull: whether to pull after cloning (or loading cache)
    """
    if cache_dir is None:
        cache_dir = os.path.join(os.path.expanduser('~'), '.cache', 'git')
    if not os.path.exists(cache_dir):
        os.makedirs(cache_dir)
    cache_dir = os.path.abspath(cache_dir)
    cache_dir = os.path.join(cache_dir, hashlib.sha1(uri).hexdigest())
    if not os.path.exists(cache_dir):
        os.makedirs(cache_dir)
    if not os.path.exists(os.path.join(cache_dir, '.git')):
        if chdir:
            os.chdir(cache_dir)
        subprocess.check_call(['git', 'clone', uri])
    else:
        if chdir:
            os.chdir(cache_dir)
        if pull:
            subprocess.check_call(['git', 'pull'])
    if reflect:
        subprocess.check_call(['git','reflog', 'expire', '--all', '--expire=now'])
        subprocess.check_call(['git', 'gc', '--prune=now'])
    return cache_dir

