def execute(self, correlation_id, command, args):
        """
        Executes a ICommand command specificed by its name.

        :param correlation_id: (optional) transaction id to trace execution through call chain.

        :param command: the name of that command that is to be executed.

        :param args: the parameters (arguments) to pass to the command for execution.

        :return: the execution result.

        :raises: ValidationException: when execution fails for any reason.
        """
        if self._logger is not None:
            self._logger.debug(
                "Executing command: {0} with args: {1}".format(command, args))

        if command is None:
            raise ValidationException(
                "Command name must not be null or empty")

        if args is None:
            args = {}

        command_handler = self._command_handlers.get(command)
        if command_handler is None:
            raise ValidationException(
                "Command handler for command: {0} is not found".format(command))

        return command_handler.execute(correlation_id, args)

