   gap_ref = r_aa == '-'
   gap_que = q_aa == '-'
   match = r_aa == q_aa
   if matches and not match:
      # End match block
      cigar.append(":%s"%len(matches))
      matches = []
   if insertion and not gap_ref:
      # End insertion
      cigar.append("+%s"%''.join(insertion))
      insertion = []
   elif deletion and not gap_que:
      # End deletion
      cigar.append("-%s"%''.join(deletion))
      deletion = []
   if gap_ref:
      if insertion:
         # Extend insertion
         insertion.append(q_aa)
      else:
         # Start insertion
         insertion = [q_aa]
   elif gap_que:
      if deletion:
         # Extend deletion
         deletion.append(r_aa)
      else:
         # Start deletion
         deletion = [r_aa]
   elif match:
      if matches:
         # Extend match block
