def create_items(portal_type=None, uid=None, endpoint=None, **kw):
    """ create items

    1. If the uid is given, get the object and create the content in there
       (assumed that it is folderish)
    2. If the uid is 0, the target folder is assumed the portal.
    3. If there is no uid given, the payload is checked for either a key
        - `parent_uid`  specifies the *uid* of the target folder
        - `parent_path` specifies the *physical path* of the target folder
    """
    if uid is None:
        uid = 0
    if portal_type is None:
        portal_type = 'Folder'
    if endpoint is None:
        endpoint = '/plone'
    if uid == 0:
        parent = api.portal.get()
    else:
        parent = api.content.get(UID=uid)
    if parent is None:
        raise ValueError('No parent found for uid %s' % uid)
    if 'parent_uid' in kw:
        parent = api.content.get(UID=kw['parent_uid'])
    if 'parent_path' in kw:
        parent = api.content.get(path=kw['parent_path'])
    if parent is None:
        raise ValueError('No parent found for uid %s' % uid)
    if parent.portal_type!= 'Folder':
        raise ValueError('Parent is not a folder')
    item = api.content.create(
        type=portal_type,
        container=parent,
        **kw
    )
    return item

