def store_in_internal_db(args, hsm, modhex_id, public_id, kh, aead):
    """ Store record (AEAD) in YubiHSM internal DB """
    # 1. Store record in internal DB
    # 1.1. Get record from HSM
    record = hsm.get_record(modhex_id)
    # 1.2. Store record in internal DB
    if record is None:
        raise Exception("Record not found in HSM")
    if record.public_id!= public_id:
        raise Exception("Public ID mismatch")
    if record.kh!= kh:
        raise Exception("Key handle mismatch")
    if record.aead!= aead:
        raise Exception("AEAD mismatch")
    # 1.3. Store record in internal DB
    record.store_in_internal_db(args.db_path)

