def imgAverage(images, copy=True):
    """
    returns an image average

    works on many, also unloaded images
    minimises RAM usage
    """
    if copy:
        images = images.copy()
    if len(images.shape) == 3:
        images = images[:, :, :, None]
    if images.shape[-1] == 1:
        images = images[:, :, :, 0]
    if images.shape[-1] == 3:
        images = images.transpose(3, 0, 1, 2)
    return np.mean(images, axis=0)

