def add_position_pattern(self, m):
        """This method draws the position adjustment patterns onto the QR
        Code. All QR code versions larger than one require these special boxes
        called position adjustment patterns.
        """
        # Position adjustment patterns are only used in QR Codes of version 2
        # or higher.
        if self.version < 2:
            return

        # The position adjustment patterns are a 5x5 square in the middle of
        # the QR Code.
        topLeft = self.modules[2]
        for i in range(5):
            if i == 0 or i == 4:
                self.modules[8 + i] = topLeft
            else:
                self.modules[12 + i] = topLeft

        # Each position adjustment pattern is a smaller 5x5 square, offset by
        # 1 module in each direction from the primary pattern.
        for i in range(2):
            for j in range(2):
                topLeft = self.modules[12 + j * 5]
                for k in range(5):
                    if k == 0 or k == 4:
                        self.modules[12 + j * 5 + k] = topLeft
                    else:
                        self.modules[12 + j * 5 + k] = self.modules[i * 5 + k]

