def _tensor_decompose_series(lhs, rhs):
    """Simplification method for lhs << rhs

    Decompose a series product of two reducible circuits with compatible block
    structures into a concatenation of individual series products between
    subblocks.  This method raises CannotSimplify when rhs is a CPermutation in
    order not to conflict with other _rules.
    """
    if isinstance(rhs, CPermutation):
        raise CannotSimplify

    if isinstance(rhs, CSeries):
        rhs = rhs.circuits

    if isinstance(lhs, CSeries):
        lhs = lhs.circuits

    if not isinstance(lhs, (list, tuple)):
        lhs = [lhs]

    if not isinstance(rhs, (list, tuple)):
        rhs = [rhs]

    # lhs and rhs are now lists of circuits
    lhs_blocks = [lhs[0]]
    rhs_blocks = [rhs[0]]

    for i in range(1, len(lhs)):
        if lhs[i].block_structure!= lhs[i - 1].block_structure:
            lhs_blocks.append(lhs[i])
        else:
            lhs_blocks[-1] = lhs_blocks[-1] * lhs[i]

    for i in range(1, len(rhs)):
        if rhs[i].block_structure!= rhs[i - 1].block_structure:
            rhs_blocks.append(rhs[i])
        else:
            rhs_blocks[-1] = rhs_blocks[-1] * rhs[i]

    # lhs_blocks and rhs_blocks are now lists of blocks
    lhs_series = [CSeries(lhs_blocks[0])]
    rhs_series = [CSeries(rhs_blocks[0])]

    for i in range(1, len(lhs_blocks)):
        lhs_series.append(CSeries(lhs_blocks[i]))

    for i in range(1, len(rhs_blocks)):
        rhs_series.append(CSeries(rhs_blocks[i]))

    # lhs_series and rhs_series are now lists of series products
    return CSeries(lhs_series) << CSeries(rhs_series)

