def create(self, typ, identifier, parent=None):
        """Create a new refobj with the given typ and parent

        :param typ: the entity type
        :type typ: str
        :param identifier: the refobj id. Used to identify refobjects of the same parent, element and type in the UI
        :type identifier: int
        :param parent: the parent refobject
        :type parent: refobj
        :returns: The created refobj
        :rtype: refobj
        :raises: None
        """
        if typ not in self.types:
            raise ValueError("Unknown type: %s" % typ)
        if typ not in self.types[self.type]:
            raise ValueError("Type %s not allowed for this entity" % typ)
        if parent is not None and parent.type!= typ:
            raise ValueError("Parent type %s does not match type %s" % (parent.type, typ))
        if parent is not None and parent.identifier == identifier:
            raise ValueError("Parent and child have the same identifier")
        if parent is not None and parent.identifier == 0:
            raise ValueError("Parent identifier is 0")
        if parent is not None and parent.identifier < 0:
            raise ValueError("Parent identifier is negative")
        if identifier < 0:
            raise ValueError("Identifier is negative")
        if identifier == 0:
            raise ValueError("Identifier is 0")
        if identifier in self.refobjs:
            raise ValueError("Identifier %s already exists" % identifier)
        if parent is not None:
            if parent.identifier not in self.refobjs:
                raise ValueError("Parent identifier %s does not exist" % parent.identifier)
            if parent.type not in self.types[self.type]:
                raise ValueError("Parent type %s does not match type %s" % (parent.type, typ))
            if parent.identifier in self.refobjs[typ]:
                raise ValueError("Parent identifier %s already exists" % parent.identifier)
        refobj = refobj(typ, identifier, parent)
        self.refobjs[typ][identifier] = refobj
        if parent is not None:
            self.refobjs[typ][parent.identifier].children[typ].append(refobj)
        return refobj

