def get(self, key):
        """Vyper is essentially repository for configurations.
        `get` can retrieve any value given the key to use.
        `get` has the behavior of returning the value associated with the first
        place from where it is set. Viper will check in the following order:
        override, arg, env, config file, key/value store, default.
        """
        if key in self._override:
            return self._override[key]
        if key in self._args:
            return self._args[key]
        if key in self._env:
            return self._env[key]
        if key in self._config_file:
            return self._config_file[key]
        if key in self._key_value_store:
            return self._key_value_store[key]
        if key in self._defaults:
            return self._defaults[key]
        raise KeyError(key)

