def _tupleCompare(tuple1, ineq, tuple2,
                 eq=lambda a,b: (a==b),
                 ander=AND,
                 orer=OR):
    """
    Compare two 'in-database tuples'.  Useful when sorting by a compound key
    and slicing into the middle of that query.
    """
    if ineq == '==':
        return eq(tuple1, tuple2)
    elif ineq == '!=':
        return not eq(tuple1, tuple2)
