def update(gandi, resource, cmdline, kernel, name, size,
           snapshotprofile, delete_snapshotprofile, background):
    """ Update a disk.

    Resource can be a disk name, or ID
    """
    if resource is None:
        raise exceptions.CommandError("You must specify a disk name or ID")

    if snapshotprofile is not None and delete_snapshotprofile is not None:
        raise exceptions.CommandError("You cannot specify both snapshotprofile and delete_snapshotprofile")

    if snapshotprofile is not None:
        if not snapshotprofile.startswith("snapshotprofile-"):
            snapshotprofile = "snapshotprofile-%s" % snapshotprofile
        if not snapshotprofile in gandi.snapshotprofiles.list():
            raise exceptions.CommandError("Snapshot profile %s does not exist" % snapshotprofile)

    if delete_snapshotprofile is not None:
        if not delete_snapshotprofile.startswith("snapshotprofile-"):
            delete_snapshotprofile = "snapshotprofile-%s" % delete_snapshotprofile
        if not delete_snapshotprofile in gandi.snapshotprofiles.list():
            raise exceptions.CommandError("Snapshot profile %s does not exist" % delete_snapshotprofile)

    if name is not None:
        if not name.startswith("disk-"):
            name = "disk-%s" % name

    if size is not None:
        if size < 1:
            raise exceptions.CommandError("Disk size must be greater than 0")

    if kernel is not None:
        if not kernel.startswith("kernel-"):
            kernel = "kernel-%s" % kernel
        if not kernel in gandi.kernels.list():
            raise exceptions.CommandError("Kernel %s does not exist" % kernel)

    if not resource.startswith("disk-"):
        resource = "disk-%s" % resource

    if not resource in gandi.disks.list():
        raise exceptions.CommandError("Disk %s does not exist" % resource)

    if name is not None:
        gandi.disks.update(resource, name=name)

    if size is not None:
        gandi.disks.update(resource, size=size)

    if kernel is not None:
        gandi.disks.update(resource, kernel=kernel)

    if snapshotprofile is not None:
        gandi.disks.update(resource, snapshotprofile=snapshotprofile)

    if delete_snapshotprofile is not None:
        gandi.disks.update(resource, snapshotprofile=None)

    if background is not None:
        gandi.disks.update(resource, background=background)

