def job(func_or_queue=None, connection=None, *args, **kwargs):
    """
    The same as RQ's job decorator, but it works automatically works out
    the ``connection`` argument from RQ_QUEUES.

    And also, it allows simplified ``@job`` syntax to put job into
    default queue.
    """
    if callable(func_or_queue):
        func = func_or_queue
        queue = 'default'
    else:
        func = None
        queue = func_or_queue or 'default'

    if not isinstance(queue, basestring):
        queue = unicode(queue)

    try:
        queue = get_queue(queue)
        if connection is None:
            connection = queue.connection
    except KeyError:
        pass

    decorator = _job(queue, connection=connection, *args, **kwargs)
    if func:
        return decorator(func)
    return decorator

mgc_code:
def job(func_or_queue=None, connection=None, *args, **kwargs):
    """
    The same as RQ's job decorator, but it works automatically works out
    the ``connection`` argument from RQ_QUEUES.

    And also, it allows simplified ``@job`` syntax to put job into
    default queue.
    """
    if func_or_queue is None:
        return functools.partial(job, connection=connection)

    if isinstance(func_or_queue, Queue):
        queue = func_or_queue
    else:
        queue = get_queue(connection)

    if queue is None:
        raise ValueError("No queue found for connection %r" % connection)

    return rq.job(queue, func_or_queue, *args, **kwargs)

