def open(cls, sock, chunk_type, isatty, chunk_eof_type=None, buf_size=None, select_timeout=None):
    """Yields the write side of a pipe that will copy appropriately chunked values to a socket."""
    if chunk_eof_type is None:
        chunk_eof_type = cls.CHUNK_EOF_TYPE
    if buf_size is None:
        buf_size = cls.BUF_SIZE
    if select_timeout is None:
        select_timeout = cls.SELECT_TIMEOUT
    while True:
        chunk = yield
        if chunk is None:
            break
        if chunk_type == cls.CHUNK_TYPE_BINARY:
            chunk = chunk.tobytes()
        elif chunk_type == cls.CHUNK_TYPE_TEXT:
            chunk = chunk.encode('utf-8')
