def merge_deployment_data(dict1: DeployedContracts, dict2: DeployedContracts) -> DeployedContracts:
    """ Take contents of two deployment JSON files and merge them

    The dictionary under 'contracts' key will be merged. The 'contracts'
    contents from different JSON files must not overlap. The contents
    under other keys must be identical.
    """
    merged = dict1.copy()
    for key, value in dict2.items():
        if key == 'contracts':
            for contract_name, contract_data in value.items():
                if contract_name in merged['contracts']:
                    raise ValueError(
                        f"Contract {contract_name} is defined in both "
                        f"deployment files"
                    )
                merged['contracts'][contract_name] = contract_data
        elif key in merged:
            if merged[key]!= value:
                raise ValueError(
                    f"Deployment files have different values for key "
                    f"'{key}'"
                )
        else:
            merged[key] = value
    return merged

