def tryParenthesisBeforeBrace(self, block, column):
        """ Character at (block, column) has to be a '{'.
        Now try to find the right line for indentation for constructs like:
          if (a == b
              and c == d) { <- check for ')', and find '(', then return its indentation
        Returns input params, if no success, otherwise block and column of '('
        """
        if block < 0 or column < 0:
            return block, column
        if block >= len(self.lines):
            return block, column
        if column >= len(self.lines[block]):
            return block, column
        if self.lines[block][column]!= '{':
            return block, column
        if column == 0:
            return block, column
        if self.lines[block][column - 1] == '(':
            return block, column - 1
        if self.lines[block][column - 1] =='':
            return block, column - 1
        if self.lines[block][column - 1] == '\t':
            return block, column - 1
        return self.tryParenthesisBeforeBrace(block - 1, self.lines[block].rfind('('))

