        the declaration.
    wrap : bool
        Whether to wrap the serialized enum.

    Returns
    -------
    str
        The serialized dzn representation of the enum.
    """
    if declare:
        return "enum {} {{".format(enum_type.name)
    else:
        return "{"

    if assign:
        return "{} = {};".format(enum_type.name, enum_type.value)
    else:
