def time_wait(
    predicate,
    timeout_seconds=120,
    sleep_seconds=1,
    ignore_exceptions=True,
    inverse_predicate=False,
    noisy=True,
    required_consecutive_success_count=1):
    """ waits or spins for a predicate and returns the time of the wait.
        An exception in the function will be returned.
        A timeout will throw a TimeoutExpired Exception.

    """
    start_time = time.time()
    consecutive_success_count = 0
    while True:
        try:
            if predicate():
                consecutive_success_count += 1
                if consecutive_success_count >= required_consecutive_success_count:
                    return time.time() - start_time
            else:
                consecutive_success_count = 0
            time.sleep(sleep_seconds)
        except Exception as e:
            if ignore_exceptions:
                if noisy:
                    print(e)
            else:
                raise e
        if time.time() - start_time > timeout_seconds:
            raise TimeoutExpired(
                "Timeout expired after {} seconds".format(timeout_seconds))

