    for name, work_bam in zip(names, work_bams):
        bam = pysam.AlignmentFile(work_bam, 'rb')
        bams.append(bam)

    # Get paired reads
    if pairmode == 'all':
        paired_reads = _get_paired_reads_all(bams)
    elif pairmode == 'proper':
        paired_reads = _get_paired_reads_proper(bams)
    elif pairmode == 'none':
        paired_reads = _get_paired_reads_none(bams)
    else:
        raise ValueError('Unknown pairmode: {}'.format(pairmode))

