def analyse(file, length=None):
    """Analyse application layer packets.

    Keyword arguments:
        * file -- bytes or file-like object, packet to be analysed
        * length -- int, length of the analysing packet

    Returns:
        * Analysis -- an Analysis object from `pcapkit.analyser`

    """
    if isinstance(file, bytes):
        file = io.BytesIO(file)
    elif not isinstance(file, io.IOBase):
        raise TypeError(f'Unsupported type: {type(file)}')

    if length is None:
        length = len(file.read())
    file.seek(0)

    return analyser.Analyser(file, length=length)

