def _em_conversion(orig_units, conv_data, to_units=None, unit_system=None):
    """Convert between E&M & MKS base units.

    If orig_units is a CGS (or MKS) E&M unit, conv_data contains the
    corresponding MKS (or CGS) unit and scale factor converting between them.
    This must be done by replacing the expression of the original unit
    with the new one in the unit expression and multiplying by the scale
    factor.
    """
    if to_units is None:
        to_units = orig_units

    if unit_system is None:
        unit_system = _unit_system_from_units(orig_units)

    if unit_system == 'cgs':
        if orig_units in _cgs_units:
            if to_units in _cgs_units:
                return _cgs_units[to_units] * _cgs_units[orig_units]
            else:
                return _cgs_units[to_units] * conv_data
        else:
            if to_units in _cgs_units:
                return _cgs_units[orig_units] * conv_data
            else:
                return _cgs_units[to_units] * _cgs_units[orig_units] * conv_data
    else:
        if orig_units in _mks_units:
            if to_units in _mks_units:
                return _mks_units[to_units] * _mks_units[orig_units]
            else:
                return _mks_units[to_units] * conv_data
        else:
            if to_units in _mks_units:
                return _mks_units[orig_units] * conv_data
            else:
                return _mks_units[to_units] * _mks_units[orig_units] * conv_data

